def transform(grid):
    # Delete the connected 3/9 object having the greatest count of 9 markers.
    H, W = len(grid), len(grid[0])
    seen=set(); comps=[]
    for r in range(H):
      for c in range(W):
        if grid[r][c] in (3,9) and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); cells=[]
          while stack:
            y,x=stack.pop(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              q=(y+dy,x+dx)
              if 0<=q[0]<H and 0<=q[1]<W and grid[q[0]][q[1]] in (3,9) and q not in seen:
                seen.add(q); stack.append(q)
          comps.append(cells)
    out=[row[:] for row in grid]
    # Objects are visually separated; restore background for object carrying more 9s.
    cells=max(comps,key=lambda cs:sum(grid[y][x]==9 for y,x in cs))
    for y,x in cells: out[y][x]=0
    return out
PY

